def source_states(live,name=SOURCE):
    installed=PROTOTYPE in live;before=live
    if installed:
        for old,new in reversed(STEPS[name]):
            if before.count(new)!=1:raise ValueError('Constructor installed source differs: '+name)
            before=before.replace(new,old,1)
    after=before
    for old,new in STEPS[name]:
        if after.count(old)!=1:raise ValueError('Constructor predecessor source differs: '+name)
        after=after.replace(old,new,1)
    if installed and after!=live:raise ValueError('Constructor source reversal failed: '+name)
    return before,after,installed
